def algorithm(func, dim, lb, ub, budget, rng):
    n = len(rng)
    D = 1e-5 * np.eye(n)
    mu = np.array([0.] * n)
    sigma = 0.5 * (ub - lb)

    for _ in range(budget):
        while True:
            try:
                Xc = rng.normal(loc=mu, scale=sigma, size=(n,))
                Xc = np.clip(Xc, a_min=lb, a_max=ub)
                f_Xc = func(Xc)
                break
            except OverflowError:
                sigma *= 0.5

        while True:
            try:
                Xp = rng.normal(loc=mu, scale=sigma, size=(n,))
                Xp = np.clip(Xp, a_min=lb, a_max=ub)
                f_Xp = func(Xp)
                break
            except OverflowError:
                sigma *= 0.5

        D += 1/(n+2) * (Xc - mu)[np.newaxis, :] @ (Xc - mu).T + \
             1/(n+2) * (Xp - mu)[np.newaxis, :] @ (Xp - mu).T
        mu = mu + 1/(n+1) * sigma**2 * ((Xc - mu)/sigma**2 + (Xp - mu)/sigma**2)

    return mu

def algorithm(func, dim, lb, ub, budget, rng):
    D = rng.uniform(lb, ub, size=(dim,))
    pop = np.stack([D + rng.normal(size=dim, scale=1) for _ in range(budget)], axis=0)

    for t in range(1, budget):
        temp = 2 / (t + 10)
        F = rng.uniform(0.5, 1, size=(len(pop),))

        for i in np.random.choice(len(pop), len(pop), replace=True):
            ind = pop[i]
            if rng.rand() < temp:
                mutation = F * (ind - pop[rng.randint(0, len(pop) - 1)])
            else:
                mutation = rng.normal(size=dim, scale=2)

            candidate = np.clip(np.round(ind + mutation), lb, ub)
            if func(candidate) < func(pop[i]):
                pop[i] = candidate
        D = np.mean(pop, axis=0)

    return D

